"use strict";
import { useState, useCallback } from "react";
import { Flex, Input, Text, useSporeColors } from "ui/src";
import { Wallet, AlertTriangle } from "ui/src/components/icons";
import styled from "styled-components";
import { isAddress } from "viem";
import { useAccount } from "wagmi";
import { useModifyLockContext } from "../ModifyLockContextProvider";
const ErrorContainer = styled(Flex)`
  background-color: ${({ $colors }) => $colors.surface2.val};
  border: 1px solid ${({ $colors }) => $colors.statusCritical.val};
  border-radius: 12px;
  padding: 12px;
  margin-top: 12px;
`;
const InputContainer = styled(Flex)`
  border-color: ${({ $colors, $hasError }) => $hasError ? $colors.statusCritical.val : $colors.surface3.val};
  
  &:focus-within {
    border-color: ${({ $colors, $hasError }) => $hasError ? $colors.statusCritical.val : $colors.neutral2.val};
  }
`;
export default function Transfer() {
  const { formData, updateFormData } = useModifyLockContext();
  const { address: account } = useAccount();
  const colors = useSporeColors();
  const [addressError, setAddressError] = useState(null);
  const validateAddress = useCallback((address) => {
    if (!address) {
      setAddressError(null);
      return true;
    }
    if (!isAddress(address)) {
      setAddressError("Invalid Ethereum address format");
      return false;
    }
    if (address === "0x0000000000000000000000000000000000000000") {
      setAddressError("Cannot transfer to zero address");
      return false;
    }
    if (account && address.toLowerCase() === account.toLowerCase()) {
      setAddressError("Cannot transfer to your own address");
      return false;
    }
    setAddressError(null);
    return true;
  }, [account]);
  const handleAddressChange = useCallback((address) => {
    updateFormData({ transferToAddress: address });
    validateAddress(address);
  }, [updateFormData, validateAddress]);
  return <Flex mt={"$gap36"}>
      <Flex row justifyContent="space-between" alignItems="center" gap={"$gap12"} mb={"$gap12"}>
        <Text variant="buttonLabel3">Transfer to</Text>
      </Flex>

      <InputContainer
    grow
    flexDirection="column"
    gap={"$gap8"}
    borderWidth={1}
    borderRadius={"$rounded12"}
    transition="border-color 0.3s ease"
    row
    alignItems="center"
    justifyContent="space-between"
    px={"$padding16"}
    $colors={colors}
    $hasError={!!addressError}
  >
        <Input
    py={"$padding20"}
    placeholderTextColor={"$neutral3"}
    placeholder="0x1234567890123456789012345678901234567890"
    fontSize={"$medium"}
    backgroundColor={"none"}
    width={"100%"}
    value={formData.transferToAddress}
    onChangeText={handleAddressChange}
  />
        <Wallet size={"$icon.20"} color={"$neutral3"} />
      </InputContainer>

      {addressError ? <ErrorContainer $colors={colors}>
          <Flex row gap={"$gap8"} alignItems="center">
            <AlertTriangle size={"$icon.16"} color={colors.statusCritical.val} />
            <Text variant="body3" color={colors.statusCritical.val}>
              {addressError}
            </Text>
          </Flex>
        </ErrorContainer> : <Text variant="body3" color={"$neutral3"} mt={"$gap12"}>
          Wallet address where the lock will be transferred. This action cannot be undone.
        </Text>}

      {formData.transferToAddress && !addressError && <Flex mt={"$gap12"} p={"$padding12"} backgroundColor={"$surface2"} borderRadius={"$rounded8"}>
          <Text variant="body3" color={"$neutral2"}>
            Lock will be transferred to: {formData.transferToAddress}
          </Text>
        </Flex>}
    </Flex>;
}
