"use strict";
import React, { useMemo, useCallback, useEffect, useState } from "react";
import { useAccount } from "wagmi";
import { Flex, Text, Loader, useSporeColors } from "ui/src";
import { AlertTriangle, Clock } from "ui/src/components/icons";
import styled from "styled-components";
import Dropdown from "./SelectLock";
import { useModifyLockContext } from "../ModifyLockContextProvider";
import { useVeABXUserLocks } from "../../../../hooks/useVeABXLocks";
import { formatABXAmount, formatVotingPower } from "../../../../utils/lockCalculations";
import { useHasVoted, useEscrowType, useLockDetails } from "../../../../hooks/useMergeValidation";
const ErrorContainer = styled(Flex)`
  background-color: ${({ $colors }) => $colors.surface2.val};
  border: 1px solid ${({ $colors }) => $colors.statusCritical.val};
  border-radius: 12px;
  padding: 12px;
  margin-top: 12px;
`;
const WarningContainer = styled(Flex)`
  background-color: ${({ $colors }) => $colors.surface2.val};
  border: 1px solid ${({ $colors }) => $colors.accentWarning.val};
  border-radius: 12px;
  padding: 12px;
  margin-top: 12px;
`;
export default function Merge() {
  const { address: account } = useAccount();
  const { selectedLockId, formData, updateFormData } = useModifyLockContext();
  const { data: userLocks, isLoading: isLoadingLocks } = useVeABXUserLocks(account);
  const colors = useSporeColors();
  const [validationErrors, setValidationErrors] = useState([]);
  const [validationWarnings, setValidationWarnings] = useState([]);
  const { data: sourceHasVoted } = useHasVoted(formData.selectedMergeLockId);
  const { data: sourceEscrowType } = useEscrowType(formData.selectedMergeLockId);
  const { data: sourceLockDetails } = useLockDetails(formData.selectedMergeLockId);
  const { data: targetEscrowType } = useEscrowType(selectedLockId || void 0);
  const { data: targetLockDetails } = useLockDetails(selectedLockId || void 0);
  const currentLock = useMemo(() => {
    return userLocks?.find((lock) => lock.id === selectedLockId) || null;
  }, [userLocks, selectedLockId]);
  useEffect(() => {
    if (!formData.selectedMergeLockId || !selectedLockId) {
      setValidationErrors([]);
      setValidationWarnings([]);
      return;
    }
    const errors = [];
    const warnings = [];
    if (sourceHasVoted === true) {
      errors.push("Source lock has voted this epoch and cannot be merged until next Thursday");
    }
    if (sourceEscrowType !== void 0 && sourceEscrowType !== 0) {
      warnings.push(`Source lock type: ${sourceEscrowType} (should be 0 for NORMAL locks)`);
    }
    if (targetEscrowType !== void 0 && targetEscrowType !== 0) {
      warnings.push(`Target lock type: ${targetEscrowType} (should be 0 for NORMAL locks)`);
    }
    if (sourceLockDetails?.isPermanent === true) {
      errors.push("Permanent locks cannot be merged from (only merged into)");
    }
    if (targetLockDetails && !targetLockDetails.isPermanent) {
      const now = Math.floor(Date.now() / 1e3);
      const targetEnd = Number(targetLockDetails.end);
      if (targetEnd <= now) {
        errors.push("Target lock has expired and cannot receive merges");
      }
    }
    setValidationErrors(errors);
    setValidationWarnings(warnings);
  }, [
    formData.selectedMergeLockId,
    selectedLockId,
    sourceHasVoted,
    sourceEscrowType,
    targetEscrowType,
    sourceLockDetails,
    targetLockDetails
  ]);
  const mergeableLocks = useMemo(() => {
    if (!userLocks || !currentLock) return [];
    return userLocks.filter((lock) => {
      if (lock.id === currentLock.id) return false;
      if (lock.managed || currentLock.managed) return false;
      if (!lock.permanent) {
        const now = Date.now() / 1e3;
        const lockEnd = parseInt(lock.lockEnd);
        if (lockEnd <= now) return false;
      }
      return true;
    });
  }, [userLocks, currentLock]);
  if (isLoadingLocks) {
    return <Flex mt={"$gap36"} alignItems="center" justifyContent="center" py="$spacing20">
        <Loader size={20} />
        <Text variant="body3" color="$neutral2" ml="$spacing8">
          Loading locks...
        </Text>
      </Flex>;
  }
  if (!currentLock) {
    return <Flex mt={"$gap36"}>
        <Text>Selected lock not found. Lock ID: {selectedLockId}</Text>
      </Flex>;
  }
  const largerLocks = useMemo(() => {
    if (!userLocks || !currentLock) return [];
    return userLocks.filter((lock) => {
      if (lock.id === currentLock.id) return false;
      if (lock.managed || currentLock.managed) return false;
      const currentLockAmount = BigInt(currentLock.amount);
      const sourceLockAmount = BigInt(lock.amount);
      return sourceLockAmount > currentLockAmount;
    });
  }, [userLocks, currentLock]);
  if (mergeableLocks.length === 0) {
    return <Flex mt={"$gap36"}>
        <Text variant="body2" color={"$neutral2"} mb={"$spacing12"}>
          No mergeable locks found for Lock #{currentLock.id}
        </Text>
        
        {largerLocks.length > 0 && <ErrorContainer $colors={colors}>
            <Flex row gap={"$gap8"} alignItems="flex-start">
              <AlertTriangle size={"$icon.16"} color={colors.statusCritical.val} />
              <Flex flexDirection="column" flex={1}>
                <Text variant="body3" color={colors.statusCritical.val} mb={"$spacing8"}>
                  You have {largerLocks.length} lock(s) with more ABX that cannot be merged into this lock.
                </Text>
                <Text variant="body3" color={"$neutral2"}>
                  To merge locks, you must merge smaller locks into larger ones. Try selecting one of your larger locks instead.
                </Text>
              </Flex>
            </Flex>
          </ErrorContainer>}
      </Flex>;
  }
  const lockOptions = useMemo(() => {
    return mergeableLocks.map((lock) => {
      const abxAmount = formatABXAmount(lock.amount);
      const votingPower = formatVotingPower(lock.votingPower);
      return `Lock #${lock.id} - ${abxAmount} ABX (${votingPower} vp)`;
    });
  }, [mergeableLocks]);
  React.useEffect(() => {
    if (mergeableLocks.length > 0 && !formData.selectedMergeLockId) {
      updateFormData({ selectedMergeLockId: mergeableLocks[0].id });
    }
  }, [mergeableLocks, formData.selectedMergeLockId, updateFormData]);
  const handleLockSelect = useCallback((selectedOption) => {
    const lockId = selectedOption.match(/Lock #(\d+)/)?.[1];
    if (lockId) {
      updateFormData({ selectedMergeLockId: lockId });
    }
  }, [updateFormData]);
  return <Flex mt={"$gap36"}>
      <Text variant="buttonLabel3" color={"$neutral2"}>
        Select a lock to merge with Lock #{currentLock.id}
      </Text>
      
      <Dropdown
    options={lockOptions}
    defaultOption={lockOptions[0] || "No locks available"}
    onSelect={handleLockSelect}
  />
      
      {
    /* Validation Errors */
  }
      {validationErrors.length > 0 && <ErrorContainer $colors={colors}>
          <Flex flexDirection="column" gap={"$gap8"}>
            {validationErrors.map((error, index) => <Flex key={index} row gap={"$gap8"} alignItems="flex-start">
                <AlertTriangle size={"$icon.16"} color={colors.statusCritical.val} />
                <Text variant="body3" color={colors.statusCritical.val}>
                  {error}
                </Text>
              </Flex>)}
          </Flex>
        </ErrorContainer>}

      {
    /* Validation Warnings */
  }
      {validationWarnings.length > 0 && <WarningContainer $colors={colors}>
          <Flex flexDirection="column" gap={"$gap8"}>
            {validationWarnings.map((warning, index) => <Flex key={index} row gap={"$gap8"} alignItems="flex-start">
                <Clock size={"$icon.16"} color={colors.accentWarning.val} />
                <Text variant="body3" color={colors.accentWarning.val}>
                  {warning}
                </Text>
              </Flex>)}
          </Flex>
        </WarningContainer>}

      {
    /* General Warnings */
  }
      <Flex flexDirection="column" gap={"$gap8"} mt={"$spacing12"}>
        <Flex row alignItems="center" gap={"$gap8"} flexWrap="wrap">
          <AlertTriangle size={18} color="$statusCritical" />
          <Text variant="body3" color="$statusCritical">
            Merging is permanent and cannot be undone. The source lock will be destroyed.
          </Text>
        </Flex>
        <Text variant="body3" color={"$neutral3"}>
          Merging Lock #{formData.selectedMergeLockId || "..."} into Lock #{currentLock.id} ({formatABXAmount(currentLock.amount)} ABX).
        </Text>
      </Flex>
    </Flex>;
}
