"use strict";
import { popupRegistry } from "components/Popups/registry";
import { PopupType } from "components/Popups/types";
import { useLockContract } from "hooks/useLockContract";
import { useVeABXUserLocks, useVeABXLock } from "hooks/useVeABXLocks";
import { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import styled from "styled-components";
import { Flex, Text, useSporeColors } from "ui/src";
import { parseLockAmount, secondsToDays } from "utils/lockCalculations";
import { isAddress } from "viem";
import { useAccount } from "wagmi";
import { useModifyLockContext } from "../ModifyLockContextProvider";
import { useHasVoted, useEscrowType, useLockDetails } from "../../../../hooks/useMergeValidation";
const Button = styled.button`
  all: unset;
  padding: 16px 10px;
  background-color: ${(props) => props.$isDisabled ? props.$colors.surface2.val : props.$lock ? props.$colors.surface2Hovered.val : props.$colors.accent1.val};
  color: ${(props) => props.$lock ? props.$colors.neutral1.val : props.$colors.surface1.val};
  border-radius: 12px;
  cursor: ${(props) => props.$isDisabled ? "not-allowed" : "pointer"};
  display: flex;
  justify-content: center;
  align-items: center;
  flex: 1;
  transition: all 0.2s ease;
  opacity: ${(props) => props.$isDisabled ? 0.5 : 1};
  &:hover {
    opacity: ${(props) => props.$isDisabled ? 0.5 : 0.7};
  }
`;
export default function ChangeLockAndOptionButton() {
  const { activeOption, selectedLockId, formData } = useModifyLockContext();
  const { address: account } = useAccount();
  const colors = useSporeColors();
  const [isProcessing, setIsProcessing] = useState(false);
  const { data: currentLock } = useVeABXLock(selectedLockId || void 0);
  const { data: sourceHasVoted } = useHasVoted(formData.selectedMergeLockId);
  const { data: sourceEscrowType } = useEscrowType(formData.selectedMergeLockId);
  const { data: sourceLockDetails } = useLockDetails(formData.selectedMergeLockId);
  const { data: targetEscrowType } = useEscrowType(selectedLockId || void 0);
  const { data: targetLockDetails } = useLockDetails(selectedLockId || void 0);
  const {
    approveABX,
    increaseLockAmount,
    extendLockTime,
    lockPermanent,
    mergeLocks,
    transferLock,
    needsApproval,
    getFormattedABXBalance,
    isWritePending,
    isConfirming,
    isSuccess,
    writeError,
    transactionHash
  } = useLockContract();
  const { refetch: refetchUserLocks } = useVeABXUserLocks(account);
  const [lastAction, setLastAction] = useState(null);
  useEffect(() => {
    if (isSuccess && lastAction && transactionHash) {
      const actionDisplayNames = {
        increase: "Amount Increased",
        extend: "Lock Extended",
        permanent: "Lock Made Permanent",
        merge: "Locks Merged",
        transfer: "Lock Transferred"
      };
      popupRegistry.addPopup({
        type: PopupType.LockSuccess,
        content: {
          type: "success",
          title: actionDisplayNames[lastAction] || "Lock Updated",
          description: `Successfully ${lastAction} lock ${selectedLockId}`,
          hash: transactionHash,
          action: lastAction
        }
      }, `lock-${lastAction}-${transactionHash}`, 8e3);
      refetchUserLocks();
      setLastAction(null);
      setIsProcessing(false);
    } else if (writeError && lastAction) {
      const errorMessage = writeError.message;
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
      if (isUserRejection) {
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: "Transaction Cancelled",
            description: `${lastAction} operation was cancelled by user`,
            action: lastAction
          }
        }, `lock-${lastAction}-cancelled-${Date.now()}`, 5e3);
      } else {
        const actionDisplayNames = {
          increase: "Increase Amount",
          extend: "Extend Lock",
          permanent: "Make Permanent",
          merge: "Merge Locks",
          transfer: "Transfer Lock"
        };
        popupRegistry.addPopup({
          type: PopupType.LockError,
          content: {
            type: "error",
            title: `${actionDisplayNames[lastAction] || "Lock Update"} Failed`,
            description: `Failed to ${lastAction} lock: ${errorMessage}`,
            action: lastAction
          }
        }, `lock-${lastAction}-error-${Date.now()}`, 1e4);
      }
      setLastAction(null);
      setIsProcessing(false);
    }
  }, [isSuccess, writeError, lastAction, transactionHash, selectedLockId, refetchUserLocks]);
  const getButtonText = () => {
    switch (activeOption) {
      case "Increase":
        return "Increase";
      case "Extend":
        return formData.extendToMaxLock ? "Convert to Permanent" : "Extend Lock Time";
      case "Merge":
        return "Merge";
      case "Transfer":
        return "Transfer";
      default:
        return "Update";
    }
  };
  const canExecute = () => {
    if (!account || !selectedLockId) return false;
    switch (activeOption) {
      case "Increase": {
        const amountValidation = parseLockAmount(formData.increaseAmount);
        if (!amountValidation.isValid) return false;
        const userBalance = parseFloat(getFormattedABXBalance());
        const requestedAmount = parseFloat(formData.increaseAmount);
        return requestedAmount > 0 && requestedAmount <= userBalance;
      }
      case "Extend": {
        return (formData.extendDays > 0 || formData.extendToMaxLock) && !!currentLock && !currentLock.permanent;
      }
      case "Merge": {
        if (!formData.selectedMergeLockId || !currentLock || currentLock.managed) return false;
        if (sourceHasVoted === true) return false;
        if (sourceLockDetails?.isPermanent === true) return false;
        if (targetLockDetails && !targetLockDetails.isPermanent) {
          const now = Math.floor(Date.now() / 1e3);
          const targetEnd = Number(targetLockDetails.end);
          if (targetEnd <= now) return false;
        }
        return true;
      }
      case "Transfer": {
        if (!formData.transferToAddress || !currentLock) return false;
        if (!isAddress(formData.transferToAddress)) return false;
        if (formData.transferToAddress === "0x0000000000000000000000000000000000000000") return false;
        if (account && formData.transferToAddress.toLowerCase() === account.toLowerCase()) return false;
        return true;
      }
      default:
        return false;
    }
  };
  const executeAction = async () => {
    if (!canExecute() || isProcessing) return;
    setIsProcessing(true);
    try {
      switch (activeOption) {
        case "Increase": {
          setLastAction("increase");
          const amount = formData.increaseAmount;
          if (needsApproval(amount)) {
            await approveABX(amount);
            await new Promise((resolve) => setTimeout(resolve, 2e3));
          }
          await increaseLockAmount({
            tokenId: selectedLockId,
            amount
          });
          break;
        }
        case "Extend": {
          if (!currentLock) return;
          if (formData.extendToMaxLock) {
            setLastAction("permanent");
            await lockPermanent(selectedLockId);
          } else {
            setLastAction("extend");
            const extensionDays = formData.extendDays;
            const currentTimeSeconds = Math.floor(Date.now() / 1e3);
            const currentUnlockTime = parseInt(currentLock.lockEnd);
            const remainingDays = Math.max(0, secondsToDays(currentUnlockTime - currentTimeSeconds));
            const totalNewDuration = remainingDays + extensionDays;
            await extendLockTime({
              tokenId: selectedLockId,
              lockDurationInDays: totalNewDuration
            });
          }
          break;
        }
        case "Merge": {
          if (!formData.selectedMergeLockId || !currentLock) return;
          setLastAction("merge");
          await mergeLocks({
            fromTokenId: formData.selectedMergeLockId,
            toTokenId: selectedLockId
          });
          break;
        }
        case "Transfer": {
          if (!formData.transferToAddress || !currentLock) return;
          setLastAction("transfer");
          await transferLock({
            tokenId: selectedLockId,
            toAddress: formData.transferToAddress
          });
          break;
        }
      }
    } catch (error) {
      console.error("Transaction failed:", error);
      if (lastAction) {
        const errorMessage = error instanceof Error ? error.message : "Unknown error";
        const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied") || errorMessage.toLowerCase().includes("rejected by user");
        if (isUserRejection) {
          popupRegistry.addPopup({
            type: PopupType.LockError,
            content: {
              type: "error",
              title: "Transaction Cancelled",
              description: `${lastAction} operation was cancelled by user`,
              action: lastAction
            }
          }, `lock-${lastAction}-cancelled-${Date.now()}`, 5e3);
        } else {
          const actionDisplayNames = {
            increase: "Increase Amount",
            extend: "Extend Lock",
            permanent: "Make Permanent",
            merge: "Merge Locks",
            transfer: "Transfer Lock"
          };
          popupRegistry.addPopup({
            type: PopupType.LockError,
            content: {
              type: "error",
              title: `${actionDisplayNames[lastAction] || "Lock Update"} Failed`,
              description: `Failed to ${lastAction} lock: ${errorMessage}`,
              action: lastAction
            }
          }, `lock-${lastAction}-error-${Date.now()}`, 1e4);
        }
      }
      setLastAction(null);
    } finally {
      setIsProcessing(false);
    }
  };
  const isDisabled = !canExecute() || isProcessing || isWritePending || isConfirming;
  const isLoading = isProcessing || isWritePending || isConfirming;
  return <Flex mt={"$spacing36"} row gap={"$gap12"} alignItems="center">
      <Link to="/locks">
        <Button $lock $colors={colors}>
          <Text variant="buttonLabel3" color={"inherit"}>
            Change Lock
          </Text>
        </Button>
      </Link>
      
      <Button
    onClick={executeAction}
    $colors={colors}
    $isDisabled={isDisabled}
  >
        <Text variant="buttonLabel3" color={"inherit"}>
          {isLoading ? "Processing..." : activeOption === "Increase" && needsApproval(formData.increaseAmount) ? "Approve & Increase" : getButtonText()}
        </Text>
      </Button>
    </Flex>;
}
